import {validateInventory} from './beta.mjs';
export class CloudInventory{
 constructor(request=fetch){this.request=request;this.baselines=new Map()}
 async call(op,body){const response=await this.request('/api/cloud?'+new URLSearchParams(typeof body==='object'?{op}:{op,...body}),typeof body==='object'?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const result=await response.json();if(!response.ok){const e=Error(result.message||'No se pudo guardar en la nube.');e.status=response.status;throw e}return result}
 async get(op,query={}){const response=await this.request('/api/cloud?'+new URLSearchParams({op,...query}),{cache:'no-store'});const result=await response.json();if(!response.ok){const e=Error(result.message||'No se pudo consultar la nube.');e.status=response.status;throw e}return result}
 async load(environment){for(let attempt=0;attempt<3;attempt++){try{const first=await this.get('state',{environment});let next=first.nextOffset;while(next!==null){const page=await this.get('state',{environment,offset:next,revision:first.revision});first.products.push(...page.products);next=page.nextOffset}this.baselines.set(environment,structuredClone(first));return first}catch(e){if(e.status!==409||attempt===2)throw e}}}
 async save(data,environment,baseRevision){const old=this.baselines.get(environment);if(!old||old.revision!==baseRevision)throw Error('Actualiza el inventario antes de guardar.');const products=new Map(old.products.map(p=>[p.id,p])),events=new Set(old.events.map(e=>e.id));const payload={environment,baseRevision,requestId:crypto.randomUUID(),upserts:data.products.filter(p=>JSON.stringify(products.get(p.id))!==JSON.stringify(p)),deletes:old.products.filter(p=>!data.products.some(n=>n.id===p.id)).map(p=>p.id),events:data.events.filter(e=>!events.has(e.id))};let result;for(let i=0;i<2;i++){try{result=await this.call('commit',payload);break}catch(e){if(e.status&&e.status<500||i)throw e}}return this.load(environment)}
 async replace(data,environment,baseRevision){data=validateInventory(data);const {sessionId}=await this.call('import-start',{environment,baseRevision,productCount:data.products.length,eventCount:data.events.length});for(const kind of ['products','events']){let part=0,batch=[],size=0;const send=async()=>{if(batch.length)await this.call('import-batch',{environment,sessionId,kind,part:part++,items:batch});batch=[];size=0};for(const item of data[kind]){const n=JSON.stringify(item).length;if(batch.length&&(size+n>2100000||batch.length>=(kind==='products'?100:500)))await send();batch.push(item);size+=n}await send()}await this.call('import-finish',{environment,sessionId});return this.load(environment)}
 async backup(environment){const data=await this.load(environment);let offset=data.events.length;while(offset<data.eventTotal){const page=await this.get('events',{environment,revision:data.revision,offset});data.events.push(...page.events);offset+=page.events.length;if(!page.events.length)throw Error('No se pudo completar el historial. Intenta de nuevo.')}for(const p of data.products){if(p.photo){const response=await this.request(p.photo,{cache:'no-store'});if(!response.ok)throw Error('No se pudo descargar una foto. Intenta de nuevo.');const blob=await response.blob();p.photo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})}}const meta=await this.get('meta',{environment});if(meta.revision!==data.revision)throw Error('El inventario cambió durante la copia. Intenta de nuevo.');return validateInventory(data)}
}
